function getActiveMaterials() {
    const rows = [];
    document.querySelectorAll("#tableBody tr[data-material-row]").forEach((tr) => {
      const material = tr.getAttribute("data-material");
      const supplier = tr.querySelector('[data-field="supplier"]')?.value || "";
